"""Evaluation helpers.  Labels are consumed only here, after scores exist (R9, R10)."""

from __future__ import annotations

from typing import Dict, Sequence

import numpy as np


def roc_auc(scores: np.ndarray, y: np.ndarray) -> float:
    from sklearn.metrics import roc_auc_score

    return float(roc_auc_score(np.asarray(y).astype(int), np.asarray(scores, dtype=np.float64)))


def auc_pr(scores: np.ndarray, y: np.ndarray) -> float:
    """AUC-PR via sklearn average_precision_score (ADBench convention)."""
    from sklearn.metrics import average_precision_score

    return float(average_precision_score(np.asarray(y).astype(int), np.asarray(scores, dtype=np.float64)))


def auc_pr_trapz(scores: np.ndarray, y: np.ndarray) -> float:
    """AUC-PR as the trapezoidal area under the precision-recall curve."""
    from sklearn.metrics import precision_recall_curve

    precision, recall, _ = precision_recall_curve(
        np.asarray(y).astype(int), np.asarray(scores, dtype=np.float64)
    )
    return float(np.trapz(precision, recall))


def evaluate_scores(scores: np.ndarray, y: np.ndarray) -> Dict[str, float]:
    return {
        "auc_roc": roc_auc(scores, y),
        "auc_pr": auc_pr(scores, y),
        "auc_pr_trapz": auc_pr_trapz(scores, y),
    }


def summarize(values: Sequence[float]) -> Dict[str, float]:
    v = np.asarray(list(values), dtype=np.float64)
    if v.size == 0:
        return {"mean": float("nan"), "std": float("nan"), "min": float("nan"), "max": float("nan")}
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
    }

